import re

impl = '''import re


def mean(values):
    if not values:
        return 0
    return sum(values) / len(values)


def pct(part, whole):
    if not whole:
        return 0.0
    return round(part / whole * 100, 2)


def slug(text):
    text = str(text).strip().lower()
    text = re.sub(r"[^a-z0-9]+", "-", text)
    return text.strip("-")
'''

calc2_impl = impl + '''

def clamp(x, lo, hi):
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def is_even(n):
    return n % 2 == 0


def split_pairs(text):
    pairs = []
    for chunk in str(text).split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        key, _, value = chunk.partition("=")
        pairs.append((key.strip(), value.strip()))
    return pairs
'''

